{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Edaravone, a structurally close pyrazolone with an N-phenyl and methyl substituent, has an absolute oral bioavailability of 57% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pirfenidone, an N-phenyl methylated heterocycle with a ring carbonyl, is rapidly absorbed and displays high oral bioavailability in humans and nonclinical species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Clobazam, another N-phenyl heterocyclic drug, has 90–100% absolute oral bioavailability in humans, supporting high oral absorption for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Sulphinpyrazone, an N-phenyl-containing drug, has 90% absolute oral bioavailability, consistent with high F for phenyl-substituted heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pethidine, a phenyl-containing drug with moderate first-pass metabolism, still has absolute oral bioavailability around 0.63 in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an antipyrine-like pyrazolone. All transferable experimental evidence, including the closest analogue edaravone (57% absolute F), pirfenidone (high F), and other N-phenyl heterocycles with high oral bioavailability, supports F ≥ 20%. No evidence suggests low oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is provided.",
    "Morgan similarity scores to the evidence molecules are moderate, but the consistent direction and structural analogy reduce the impact of this gap."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

